def get_test_counts():
    n_cols = 17
    m_rows = 18

    grid = [[0]*n_cols for _ in range(m_rows)]

    # Place 2s
    last_with_2s = 9
    for r in range(m_rows):
        d = min(r, m_rows - 1 - r)
        if r <= last_with_2s:
            c_left = 8 - d
            c_right = 8 + d
            if 0 <= c_left < n_cols:
                grid[r][c_left] = 2
            if 0 <= c_right < n_cols:
                grid[r][c_right] = 2

    cycles = [1, 2, 3, 0, 0]
    target_counts = {}
    for r in range(3):
        target_counts[r] = 0
    for r in range(3, 5):
        target_counts[r] = 1
    for r in range(5, 8):
        target_counts[r] = 2
    for r in range(8, 11):
        target_counts[r] = 2
    for r in range(11, 15):
        target_counts[r] = 3
    for r in range(15, 18):
        target_counts[r] = 3

    for r in range(m_rows):
        target_count = target_counts.get(r, 0)
        if target_count == 0:
            continue

        cycle_pos = (r - 3) % 5
        active_stream = cycles[cycle_pos]

        valid_cols = [c for c in range(5, 12) if c % 5 == active_stream]
        valid_cols = [c for c in valid_cols if grid[r][c] != 2]

        num_fill = min(target_count, len(valid_cols))
        for i in range(num_fill):
            grid[r][valid_cols[i]] = 1

    return sum(grid[r][c] == 1 for c in range(n_cols)) for r in range(m_rows)

