# Debug: count how many valid columns per stream for different step values

def count_valid_columns(n_cols, step):
    results = {}
    for s in range(step * 2 if n_cols > step else n_cols // step):
        cols = [c for c in range(step, n_cols - step) if c % step == s]
        results[s] = len(cols)
    return results

